    {auto bank=model();auto other=model();NativeConstraintSchemaEmitterConsumerScopeTu15 outer(bank,policy());NativeConstraintSchemaEmitterConsumerScopeTu15 inner(other,policy());check(native_constraint_schema_emitter_policy_tu15(bank)&&native_constraint_schema_emitter_policy_tu15(other),"Nested scopes lost a bank/executor owner");}
