    {auto bank=model(0xf1234567);phase=0x31f7c3;ObservedWorldState s(bank,none,services,SourcePhysicsContactImage::TitleUpdate15);s.load(state());NativeConstraintSchemaEmitterConsumerScopeTu15 scope(bank,policy());bool rejected{};try{run_326820(s);}catch(const std::runtime_error&e){rejected=std::string(e.what()).find("unqualified actual continuation")!=std::string::npos;}check(rejected&&s.gp[4]==0x200f004&&phase==0x32a3ba&&native_constraint_schema_emitter_activity_tu15(bank).completed_calls==0,"Late actual return input was fabricated or ignored");native_constraint_schema_emitter_activity_reset_tu15(bank);}
