int main(int argc,char**argv){try{
    check(argc==2&&std::filesystem::exists(argv[1]),"Required original scoped emitter fixture absent");std::ifstream in(argv[1]);const auto f=J::parse(in);check(f.at("image_sha256")=="21b207e7efdacaf6124a0822837f8be570766a42505057f7fd2d2ba8f409c4fd"&&f.at("required_backend")=="unchanged-tu15-scoped-schema-emitter-real-parent-phase-v1","Required scoped emitter authority absent");std::size_t count{},writes{},reads{};
    for(const auto&c:f.at("cases")){
        const auto name=c.at("name").get<std::string>();Memory before;for(const auto&b:c.at("banks"))before.banks.emplace(b.at("address"),bytes(b.at("before")));before.banks[0x200effcu].resize(4);before.fault=c.value("fault",J{});before.write_fault=c.value("write_fault",J{});const bool observer_case=c.contains("observer_fault");
        for(bool read_pass:{false,true}){
            if(read_pass&&observer_case)continue;auto m=before;m.log_reads=read_pass;const bool fault_case=!m.fault.is_null()||!m.write_fault.is_null();m.log_writes=fault_case&&!read_pass;std::vector<SourcePhysicsContactRecordStore>stores;SourcePhysicsContactRecordObserver observe;if(!read_pass&&!fault_case)observe=[&](const auto&e){stores.push_back(e);if(observer_case&&stores.size()==c.at("observer_fault"))throw ObserverFault{};};
            SourcePhysicsWorldRuntimeServices services;unsigned literal_sites{};services.instruction=[&](auto){++literal_sites;};ObservedWorldState s(m,observe,services,SourcePhysicsContactImage::TitleUpdate15);s.load(state());const auto saved=s.save();bool trace1{},trace2{};std::uint32_t phase=c.at("actual_caller");std::vector<std::uint32_t>phases;NativeConstraintSchemaEmitterActivityTu15 activity;NativeConstraintSchemaEmitterConsumerScopeTu15 scope(m,{0x2000000,0x2010000,[&]{return phase;},[&](auto pc){phase=pc;phases.push_back(pc);},&trace1,&trace2,true,&activity});bool failed{},observer_failed{};
            try{run_326820(s);}catch(const Fault&){failed=true;}catch(const ObserverFault&){observer_failed=true;}
            check(activity.calls==1&&activity.live_cursor_calls==1&&literal_sites==0,name+" scoped native owner did not execute");check(failed==fault_case&&observer_failed==observer_case,name+" scoped fault/dependency completion differs");const auto after=s.save();retained(saved,after,name);if(!failed&&!observer_failed){check(after.gp[0]==c.at("boundary_gp")[0]&&after.gp[4]==0x200f004&&activity.completed_calls==1,name+" genuine scoped return ABI differs");check(phases==std::vector<std::uint32_t>({0x32a390,0x32a394,0x32a398,0x32a3a8,0x32a3aa,0x32a3ae,0x32a3b6,0x32a3ba}),name+" native actual phase publication differs");}
            if(failed)check(phase==c.at("stop_pc")&&activity.completed_calls==0,name+" source fault phase/completion differs");if(observer_failed)check(phase==c.at("writes").back().at("instruction")&&activity.completed_calls==0,name+" committed observer fault phase differs");
            if(read_pass){J expected=J::array();for(const auto&r:c.at("reads"))expected.push_back(J::array({r.at("address"),r.at("bytes")}));check(m.reads==expected,name+" scoped original read order differs");reads+=m.reads.size();}else{if(fault_case)stores=m.raw_stores;const auto&expected=c.at("writes");check(stores.size()==expected.size(),name+" scoped ordered store count differs");for(std::size_t n=0;n<stores.size();++n){const auto&a=stores[n];const auto&b=expected[n];check((fault_case||a.instruction==b.at("instruction"))&&a.address==b.at("address")&&hex(a.before)==b.at("before").get<std::string>()&&hex(a.written)==b.at("written").get<std::string>(),name+" scoped ordered store differs");}writes+=stores.size();}
            for(const auto&b:c.at("banks"))check(hex(m.banks.at(b.at("address")))==b.at("after").get<std::string>(),name+" retained scoped emitter bytes differ");check(native_constraint_schema_emitter_activity_tu15(m).calls>=1,"Missing bank activity");native_constraint_schema_emitter_activity_reset_tu15(m);
        }++count;
    }policies();std::cout<<count<<" actual3caller physical scoped native schema emissions, "<<reads<<" ordered reads and "<<writes<<" stores passed with caller GP/flags/SIMD/live x87 preserved, exact old/current state headers and explicit live unsupported-context refusals\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
